notes:
/* ONE SPRING FOR THE THROW AND THE SNAP. On release, decide
   where it lands — where it would coast to, rounded to the step —
   and let one spring carry it there, starting at the hand's own
   speed. A flick coasts, a slow release just settles. */
const land = Math.round((pos + velocity * carry) / step) * step;
v += (land - pos) * 0.045;  v *= 0.82;  pos += v;

/* a dial seen from the front: ticks fall away in height and ink */
const f = 1 - (Math.abs(x) / HALF) ** 2;
tick.style.transform = `translateX(${x}px) scaleY(${0.55 + 0.45 * f})`;
tick.style.opacity = 0.18 + 0.82 * f;
